using WorldtreeNexus.DataTypes;

namespace WorldtreeNexus.Hardcodes {
    public static class HardcodedQuests {
        public static void InitQuests(Dictionary<string, Quest> QuestLib) {
            List<Quest> toAdd = new();

            toAdd.Add(new("TI_OnTheJobTraining", "On the Job Training", "Very Short", "Novice", "You have been tasked with collecting a set of items to be able to leave the island: /n - Copper bar /n - Illusion talisman /n - Attack potion /n - Cleansed bones /n - Small coin pouch /n - Poplar shortbow /n - Cozy Cottages teleport /n - Fish and Chips", 180, new() { "Tutorial Island" }) {
                StartNPC = "guyTutorial",
                StartLoc = "TI_StartHut",
                DateFullyImplemented = 20260828,
                Rewards = { new("Item", "Gold", 1000) },
                QuestPoints = 1,
                Stages = new() {
                    { 0, new("I have spoken with Tutorial Guy, and been given a list of items to collect before I can leave the island: /n - Copper bar /n - Illusion talisman /n - Attack potion /n - Cleansed bones /n - Small coin pouch /n - Poplar shortbow /n - Cozy Cottages teleport /n - Fish and Chips /n /n He said I can try to figure out all the items myself in any order, but suggested that I speak to Farming Guy at his farmstead first if I want some guidance.", 10, quickDesc: "Speak to Farming Guy at his farmstead to learn about Farming.")},
                    { 10, new("I spoke with Farming Guy and he gave me some potato seeds. I can Activate (*) them to plant them in a place that has farming allotments, such as the farmstead, and harvest them after they grow.", 20, "PlantSeed", "seedPotato", 1, quickDesc: "Plant the three seeds you were given by Activating (*) them while at the farmstead.") },
                    { 20, new("I planted the potato seeds. While they grow, I should work on pursuing the first item on the list: a copper bar. The cavern seems like a likely place to find ores. Perhaps someone there can explain more.", 30, "PickupItem", "barCopper", 1, quickDesc: "Go to the Cavern. Grab the pickaxe and hammer from the ground. Switch to the (R)esources tab on the right, then click Copper Ore to mine it. Mine five or so, then switch to the (P)rocessing tab and use the Furnace to smelt them into copper bars.") },
                    { 30, new("Got some copper bars! I should try smithing them into things at the Anvil. A sword seems useful.", 40, "PickupItem", "swordCopper", 1, quickDesc: "In the Cavern (P)rocessing tab, click the Anvil to begin smithing. Create a copper sword, hatchet, and at least 45 nails.") },
                    { 40, new("I'm armed and dangerous! Seems like there's a cage with some giant guinea pigs and a grizzled instructor in the caverns, perhaps he can tell me about combat.", 50, "Kill", "cuyGiant", 2, quickDesc: "Go into the Giant Guinea Pig cage in the cavern and kill two of them, collecting at least two bones and an eye.") },
                    { 50, new("With my bloodlust sated I should work on the next item on the list. 'Illusion talisman', I can probably find someone to tell me more about talismans. I saw a Magic Altar, that's a good place to start for something that sounds magical.", 60, "PickupItem", "talismanIllusion", quickDesc: "Speak to Talisman Guy to receive some supplies to perform Alchemy and talisman drawing. Go to the Agility Course to pick a midori and a neela, then combine the midori in a vial of water with ground bones. Use a second vial of water on the mixture, then use both resulting mixtures on your brazier to make ink. Get the instructions to make paper from Talisman Guy or buy it from him, then draw an illusion talisman.") },
                    { 60, new("One illusion talisman acquired! Next up I need an attack potion, so I should use the tools Talisman Guy gave me to make one. He may be able to tell me how to get the ingredients needed.", 70, "PickupItem", "potionAttack", quickDesc: "Combine a clean neela with a cuy eye in a vial of water, then heat it with your brazier to make an attack potion.") },
                    { 70, new("Three items down, five to go! 'Cleansed bones' sounds like some kind of burial rite? Perhaps someone in the Temple can explain more.", 80, "PickupItem", "bonesRegularCleansed", quickDesc: "Take a set of bones to the Temple and use the Holy Fountain to process them into cleansed bones.") },
                    { 80, new("Some clean bones ready to hand in. Next is a small coin pouch. The only thing I can think of that might result in a coin pouch is pickpocketing someone. I've seen a dodgy-looking fellow around the island, perhaps he has some tips for me.", 90, "PickupItem", "coinPouchSmall", quickDesc: "Go to the Crossroads. In the (N)PC menu on the right of your screen, click the P to the right of Dodgy Ranger Guy's name to pickpocket him until you succeed.") },
                    { 90, new("Stealing from someone who knows you're stealing from them doesn't seem like the best training, but I've got a coin pouch now. Next I need a poplar shortbow. Dodgy Ranger Guy can tell me more about that.", 100, "PickupItem", "shortbowPoplar", quickDesc: "Cut a poplar tree to get a log. Activate (*) a knife to open the fletching menu, then make a poplar shortbow (u). Pick a piece of flax at the Magic Altar, spin it into a bowstring with the Spinning Wheel in the Wizard Hut, then use the string on the bow.") },
                    { 100, new("Properly feeling like Robin Hood, now. One of the last items I need is a 'Cozy Cottages teleport'. Sounds house related, perhaps the Estate Agent in the bank can explain.", 110, "PickupItem", "teleportCozyCottages", quickDesc: "Go to the Bank. Speak to the Estate Agent about work, and receive a Cozy Cottages contract. Go to the place specified with planks and nails (and possible bolts of cloth and candles) and repair each of the furniture pieces in the Minigame (*) menu on the right of your screen. Do this twice, then speak to the Estate Agent about Rewards to purchase a teleport scroll for two points.") },
                    { 110, new("I suppose all that's left is those fish and chips. I wonder how my potatoes are doing?", 120, "PickupItem", "potato", quickDesc: "Go harvest the potatoes you grew earlier. If you already harvested them but still have a potato, you should be able to drop and pickup a potato again to move on. Otherwise grow more potatoes.") },
                    { 120, new("Potatoes acquired. I can probably cut them into shape by using a knife on them. Wasn't there a deep fryer in the Kitchen?", 130, "PickupItem", "potatoSticksFried", quickDesc: "Use a knife on a potato to turn it into slices, then the knife on the slices to make potato sticks. Go to the Kitchen and use the Deep Fryer to fry the potato sticks.") },
                    { 130, new("Now I've got 'and chips', still need a fish. Maybe there's a fisherman at the Docks who can tell me about fishing.", 140, "PickupItem", "fishRawPollock", quickDesc: "Speak to Fishing Guy at the Docks to receive a poplar rod, then fish in the Sea Shallows to get a pollock.") },
                    { 140, new("Can't very well cook the fish like this, better prepare it with my trusty knife.", 150, "PickupItem", "fishFilletPollock", quickDesc: "Use a knife on the raw pollock to fillet it.") },
                    { 150, new("The fish bit somewhat handled, though I need to batter it before I can fry it to make proper fishsticks. Batter needs at least an egg and some flour. Everything I need should be at the farmstead.", 160, "PickupItem", "fishSticks", quickDesc: "Get a pot and bowl from the Kitchen, then go to the farmstead. Pick up an egg and use it on the bowl, then pick wheat and use the Windmill to turn it into flour. Use the flour on the bowl of egg to make a bowl of batter. Use the pollock fillet on the batter to batter it, then cook it in the Kitchen with the Deep Fryer.") },
                    { 160, new("My victory is close at hand! I just have to use the fish sticks on the fried potato sticks to turn them into fish and chips. I should be careful not to accidentally eat them, though!", 170, "PickupItem", "mealFishChips", quickDesc: "Use the fish sticks on the fried potato sticks to make fish and chips. Be careful not to activate them, as that will cause you to eat them.") },
                    { 170, new("That's every item on the list! I just have to go speak to Wizard Atrel to turn them all in.", 180, quickDesc: "Take all of the items from the list to Wizard Atrel in his hut to complete the quest.") },
                    { 180, new("What a romp! I feel equipped to make my way in the world now", 180, quickDesc: "Items turned in, and quest completed. You may leave the island at any time now.") },
                }
            }); 

            for (int i = 0; i < toAdd.Count; i++) {
                QuestLib.Add(toAdd[i].ID, toAdd[i]);
            }
        }
    }
}
